TypeScript example (streaming adapter):

// adapter.ts
import { Readable } from 'stream';

export type ToolEvent = { type: 'progress' | 'tool_call' | 'tool_result'; meta?: Record<string, unknown>; payload?: unknown };

// Convert a legacy callback-style tool (input, cb) into an AsyncIterator of ToolEvent
export function legacyToStream(
  runLegacyTool: (input: any, cb: (err: Error | null, res?: any) => void) => void,
  input: any
): AsyncGenerator<ToolEvent, void, unknown> {
  const queue: ToolEvent[] = [];
  let resolveNext: ((v: IteratorResult<ToolEvent>) => void) | null = null;
  let done = false;

  // wire up the callback to push events
  runLegacyTool(input, (err, res) => {
    if (err) {
      queue.push({ type: 'tool_result', meta: { error: true }, payload: { message: err.message } });
    } else {
      // imagine legacy tool provided intermediate progress callbacks via side-channel; emulate progress events here
      queue.push({ type: 'progress', payload: { pct: 100 } });
      queue.push({ type: 'tool_result', payload: res });
    }
    done = true;
    if (resolveNext) resolveNext({ value: queue.shift()!, done: false });
  });

  return (async function* () {
    while (!done || queue.length) {
      if (queue.length) {
        yield queue.shift()!;
        continue;
      }
      await new Promise<void>((r) => setTimeout(r, 5)); // small polling to keep example simple
    }
  })();
}

// Usage:
// for await (const ev of legacyToStream(myLegacyTool, { query: 'x' })) { console.log(ev); }

Go example (channel-based adapter):

package compat

import (
    "context"
)

type ToolEvent struct {
    Type   string                 `json:"type"`
    Meta   map[string]interface{} `json:"meta,omitempty"`
    Payload interface{}           `json:"payload,omitempty"`
}

// Legacy signature: func(input map[string]interface{}) (map[string]interface{}, error)
func LegacyToStream(ctx context.Context, runLegacy func(map[string]interface{}) (map[string]interface{}, error), input map[string]interface{}) (<-chan ToolEvent, <-chan error) {
    evCh := make(chan ToolEvent, 8)
    errCh := make(chan error, 1)
    go func() {
        defer close(evCh)
        // emit simple progress events while running
        // in real code we'd hook into a progress callback if available
        evCh <- ToolEvent{Type: "progress", Payload: map[string]interface{}{"pct": 10}}
        res, err := runLegacy(input)
        if err != nil {
            errCh <- err
            return
        }
        evCh <- ToolEvent{Type: "tool_result", Payload: res}
        close(errCh)
    }()
    return evCh, errCh
}

// Usage:
// evs, errs := LegacyToStream(ctx, legacyFn, input)
// for ev := range evs { fmt.Println(ev) }
